export const ANSWERS = ANSWERS_RAW.trim().split(/\s+/).filter((w) => w.length === 5)
const EXTRAS = EXTRAS_RAW.trim().split(/\s+/).filter((w) => w.length === 5)

// Union of both, deduped — the accepted-guess pool.
export const VALID_GUESSES = (() => {
  const set = new Set()
  for (const w of ANSWERS) set.add(w)
  for (const w of EXTRAS) set.add(w)
  return set
})()

export const VALID_GUESS_COUNT = VALID_GUESSES.size
